Here's a complete example with both `DataRow` and `DynamicData` approaches:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: inline constants, great for simple cases ---

    [TestMethod]
    [DataRow(10.00, 2, 20.00)]
    [DataRow(5.50, 3, 16.50)]
    [DataRow(0.00, 5, 0.00)]
    [DataRow(99.99, 1, 99.99)]
    public void CalculateTotal_ReturnsExpected(double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 10, 90.00)]   // 10% off
    [DataRow(200.00, 25, 150.00)]  // 25% off
    [DataRow(50.00, 0, 50.00)]     // no discount
    [DataRow(80.00, 100, 0.00)]    // 100% off
    public void ApplyDiscount_ReturnsExpected(double total, int discountPct, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)total, discountPct);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: use for complex objects, computed values, or decimal precision ---

    [TestMethod]
    [DynamicData(nameof(CalculateTotalCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_DynamicCases(decimal price, int quantity, decimal expected)
    {
        var result = _calculator.CalculateTotal(price, quantity);
        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> CalculateTotalCases()
    {
        yield return new object[] { 19.99m, 4, 79.96m };
        yield return new object[] { 0.01m, 100, 1.00m };
        yield return new object[] { 999.99m, 0, 0.00m };
    }

    [TestMethod]
    [DynamicData(nameof(DiscountEdgeCases), DynamicDataSourceType.Property)]
    public void ApplyDiscount_EdgeCases(decimal total, int discountPct, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discountPct);
        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> DiscountEdgeCases => new[]
    {
        new object[] { 0.01m, 50, 0.005m },
        new object[] { 1000.00m, 1, 990.00m },
        new object[] { 49.99m, 99, 0.4999m },
    };

    // --- Validation: expect exceptions for invalid input ---

    [TestMethod]
    [DataRow(-1.00, 1)]
    [DataRow(10.00, -1)]
    public void CalculateTotal_InvalidInput_Throws(double price, int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)price, quantity));
    }

    [TestMethod]
    [DataRow(100.00, -1)]
    [DataRow(100.00, 101)]
    public void ApplyDiscount_InvalidPercent_Throws(double total, int discountPct)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)total, discountPct));
    }
}
```

**Key best practices shown:**

| Technique | When to use |
|-----------|-------------|
| `[DataRow]` | Simple inline constants (note: `decimal` literals not supported, use `double` and cast) |
| `[DynamicData]` with **Method** | Computed/complex data, full `decimal` precision |
| `[DynamicData]` with **Property** | Same, but when data is static and doesn't need logic |

**Other tips:**
- One assertion per test method keeps failure messages clear
- Use `[TestInitialize]` over constructors for setup
- Name tests `Method_Scenario_Expected`
- Group edge cases and invalid inputs separately for readability
